fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    if down == 1 && prev == 0 {
        if host::display::pointer_y() < h / 2 {
            let mut i: i32 = 0;
            while i < 12 {
                host::audio::tone_at(262 + (i % 4) * 66, 180, 0, i * 250);
                i = i + 1;
            }
        } else {
            host::audio::stop(-1);
        }
    }
    host::display::state_set(0, down);
    host::display::clear(0x000000);
    host::display::fill_rect(8, 8, w - 16, h / 2 - 16, 0x103020);
    host::display::fill_rect(8, h / 2 + 8, w - 16, h / 2 - 16, 0x401010);
    host::display::draw_string(24, 24, "PLAY 3 SEC RIFF", 0xffffff, 2);
    host::display::draw_string(24, h / 2 + 24, "PANIC STOP ALL", 0xffffff, 2);
    host::display::present();
}
